import asyncio
import time

import pytest

import gw


class FakeTriton:
    """Doble del cliente async: mismos métodos y mismas excepciones que el real."""

    def __init__(self, mode="ok", delay=1.0):
        self.mode, self.delay = mode, delay

    async def infer(self):
        if self.mode == "down":
            raise ConnectionRefusedError("connection refused")
        if self.mode == "slow":
            await asyncio.sleep(self.delay)
        return [0.1, 0.9]


@pytest.mark.parametrize("mode,code", [("ok", 200), ("down", 503), ("slow", 504)])
def test_codigo_por_modo(mode, code):
    assert asyncio.run(gw.classify(FakeTriton(mode))) == code


def test_lento_corta_a_tiempo():
    t0 = time.perf_counter()
    assert asyncio.run(gw.classify(FakeTriton("slow"))) == 504
    assert time.perf_counter() - t0 < 0.3  # cortó a ≈ 0.15 s; no esperó 1 s


def test_timeout_con_monkeypatch(monkeypatch):
    monkeypatch.setattr(gw, "INFER_TIMEOUT_S", 0.001)  # solo dura este test
    assert asyncio.run(gw.classify(FakeTriton("slow", delay=0.01))) == 504
EOF

